// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(bytes32 assertionId) public {
        // The reference C's assertionDisputedCallback does not revert when called by the optimistic asserter
        // We simulate being the optimistic asserter by pranking as this contract (which is the asserter in setUp)
        vm.prank(address(this));
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.assertionDisputedCallback.selector, assertionId));
        assertTrue(success, "assertionDisputedCallback should not revert when called by optimistic asserter");
    }
}

